package parser

import (
	"fmt"
	"go/ast"
	"go/token"
	"strings"
	"sync"
)

const debugResolve = false

// ResolveFile applies the parser's deprecated
// [ast.Ident]-to-[ast.Object] resolution to the specified file's
// syntax tree. This is the same operation that is skipped on files
// parsed with the [SkipObjectResolution] mode flag.
//
// ResolveFile is idempotent and concurrency safe.
// Once ResolveFile returns, the file is resolved.
//
// Resolution error messages are discarded.
//
// Deprecated: [ast.Object] should not be used in new designs; use the
// [go/types] package instead. This function is provided to ease
// migration in applications that have disabled legacy object
// resolution by default but still need it in some circumstances.
func ResolveFile(file *ast.File) {
	doIt := func() {
		if file.Scope == nil {
			// Inv: File.Scope is set by the parser or by
			// the first doIt call for a file, and never
			// cleared, so nil implies that the file was
			// parsed without resolution and that only
			// ResolveFile will set it.

			var dummy token.File // only for declErr messages (discarded) and panics
			resolveFile(file, &dummy, func(token.Pos, string) {})

			if file.Scope == nil {
				panic("nil File.Scope")
			}
		}
	}

	// Rather than add a sync.Once field to ast.File itself,
	// we use a "singleflight"-like pattern to ensure that all
	// doIt operations on a given file are mutually exclusive.
	v, _ := resolveOnces.LoadOrStore(file, new(sync.Once))
	v.(*sync.Once).Do(doIt)
	resolveOnces.Delete(file)
}

var resolveOnces sync.Map // *ast.File -> *sync.Once

// resolveFile walks the given file to resolve identifiers within the file
// scope, updating ast.Ident.Obj fields with declaration information.
//
// If declErr is non-nil, it is used to report declaration errors during
// resolution. tok is used to format position in error messages.
func resolveFile(file *ast.File, handle *token.File, declErr func(token.Pos, string)) {
	pkgScope := ast.NewScope(nil)
	r := &resolver{
		handle:   handle,
		declErr:  declErr,
		topScope: pkgScope,
		pkgScope: pkgScope,
		depth:    1,
	}

	for _, decl := range file.Decls {
		ast.Walk(r, decl)
	}

	r.closeScope()
	assert(r.topScope == nil, "unbalanced scopes")
	assert(r.labelScope == nil, "unbalanced label scopes")

	// resolve global identifiers within the same file
	i := 0
	for _, ident := range r.unresolved {
		// i <= index for current ident
		assert(ident.Obj == unresolved, "object already resolved")
		ident.Obj = r.pkgScope.Lookup(ident.Name) // also removes unresolved sentinel
		if ident.Obj == nil {
			r.unresolved[i] = ident
			i++
		} else if debugResolve {

			// ignore automatically inserted semicolon
			if lit == "\n" {
				continue scanFile
			}
			fallthrough
		default:
			prev = pos
		}
	}
	return decls, uses
}

func annotatedObj(lit string) (name string, decl, use bool) {
	if lit[1] == '*' {
		lit = lit[:len(lit)-2] // strip trailing */
	}
	lit = strings.TrimSpace(lit[2:])

scanLit:
	for idx, r := range lit {
		switch r {
		case '=':
			decl = true
		case '@':
			use = true
		default:
			name = lit[idx:]
			break scanLit
		}
	}
	return
}

func TestResolveFile(t *testing.T) {
	const src = `package p; var x = 1; var y = x`
	fset := token.NewFileSet()
	f, err := ParseFile(fset, "example.com/p", src, SkipObjectResolution)
	if err != nil {
		t.Fatal(err)
	}
	xspec := f.Decls[0].(*ast.GenDecl).Specs[0].(*ast.ValueSpec)
	yspec := f.Decls[1].(*ast.GenDecl).Specs[0].(*ast.ValueSpec)
	x := xspec.Names[0]
	y := yspec.Names[0]
	xref := yspec.Values[0].(*ast.Ident)

	// before
	if x.Name != "x" {
		t.Fatalf("x: wrong Ident")
	}
	if y.Name != "y" {
		t.Fatalf("y: wrong Ident")
	}
	if xref.Name != "x" {
		t.Fatalf("xref: wrong Ident")
	}
	if x.Obj != nil {
		t.Fatalf("ParseFile(SkipObjectResolution) unexpectedly set x.Obj")
	}
	if y.Obj != nil {
		t.Fatalf("ParseFile(SkipObjectResolution) unexpectedly set y.Obj")
	}
	if xref.Obj != nil {
		t.Fatalf("ParseFile(SkipObjectResolution) unexpectedly set xref.Obj")
	}

	ResolveFile(f)

	// after
	if x.Obj == nil {
		t.Fatalf("after ResolveFile, x.Obj is nil")
	}
	if y.Obj == nil {
		t.Fatalf("after ResolveFile, y.Obj is nil")
	}
	if xref.Obj == nil {
		t.Fatalf("after ResolveFile, xref.Obj is nil")
	}
	if x.Obj.Kind != ast.Var {
		t.Errorf("after ResolveFile, x.Obj.Kind = %d, want Var", x.Obj.Kind)
	}
	if y.Obj.Kind != ast.Var {
		t.Errorf("after ResolveFile, y.Obj.Kind = %d, want Var", y.Obj.Kind)
	}
	if xref.Obj.Kind != ast.Var {
		t.Errorf("after ResolveFile, xref.Obj.Kind = %d, want Var", x.Obj.Kind)
	}
	if x.Obj.Name != "x" {
		t.Errorf("after ResolveFile, x.Obj.Name = %q, want \"x\"", x.Obj.Name)
	}
	if y.Obj.Name != "y" {
		t.Errorf("after ResolveFile, y.Obj.Name = %q, want \"y\"", y.Obj.Name)
	}
	if xref.Obj != x.Obj {
		t.Errorf("after ResolveFile, x.Obj != xref.Obj")
	}
	if x.Obj.Decl != xspec {
		t.Errorf("after ResolveFile, x.Obj.Decl = %+[1]v (%[1]T), want xspec", x.Obj.Decl)
	}
	if y.Obj.Decl != yspec {
		t.Errorf("after ResolveFile, y.Obj.Decl = %+[1]v (%[1]T), want yspec", y.Obj.Decl)
	}

	ResolveFile(f) // idempotent; no ill effects
}
